union all
select id, 2, $$Which window is missing from the ones being checked?$$ from new_challenge
union all
select id, 3, $$There are len(nums) - k + 1 windows. The range is missing the + 1.$$ from new_challenge;

with new_challenge as (
  insert into public.bug_challenges (
    title, language, bug_category, difficulty, function_name,
    broken_code, correct_code, problem_description, symptom_description,
    explanation, test_cases, status
  ) values (
    $$Range check excludes its own lower bound$$,
    $$python$$,
    $$off_by_one$$,
    $$medium$$,
    $$count_in_range$$,
    $$def count_in_range(nums, low, high):
    return len([n for n in nums if low < n <= high])$$,
    $$def count_in_range(nums, low, high):
    return len([n for n in nums if low <= n <= high])$$,
    $$count_in_range(nums, low, high) counts values between low and high INCLUSIVE, so count_in_range([1,2,3], 1, 3) returns 3.$$,
    $$count_in_range([1,2,3], 1, 3) returns 2 instead of 3 — a value exactly equal to low is not counted, although one equal to high is.$$,
    $$The two comparisons are inconsistent: `<` excludes low while `<=` includes high, so the range is half-open when the specification calls for it to be closed. Boundary values are exactly the inputs least likely to be tested, which is how this survives. When a spec says 'inclusive', both ends need <=. It is worth writing one test per boundary — at low, at high, and just outside each — since that is where nearly all range bugs live.$$,
    $$[{"input":[[1,2,3],1,3],"expected_output":3},{"input":[[1,2,3],2,3],"expected_output":2},{"input":[[5],1,4],"expected_output":0}]$$::jsonb,
    'published'
  )
  returning id
)
insert into public.hints (bug_challenge_id, hint_order, hint_text)
select id, 1, $$Which of the boundary values is being counted, and which is not?$$ from new_challenge
union all
select id, 2, $$Compare the two comparison operators in that condition.$$ from new_challenge
union all
select id, 3, $$'Inclusive' needs <= on both sides. Change low < n to low <= n.$$ from new_challenge;
